use ArtisanToolbox\Mosaicast\Facades\Mosaicast;
use Illuminate\Contracts\Queue\ShouldQueue;

final class ProcessOrder implements ShouldQueue
{
    public function __construct(
        public readonly string $sessionIdentifier,
        public readonly int $orderId,
    ) {}

    public function handle(): void
    {
        mosaicast()->toSession($this->sessionIdentifier)->dispatch('orders.updated', [
            'orderId' => $this->orderId,
        ]);
    }
}

import { configureEcho, echo } from "@laravel/echo-vue";
import { createInertiaApp } from "@inertiajs/vue3";
import { createMosaicast } from "@artisan-toolbox/mosaicast";

configureEcho({
  broadcaster: "reverb",
  key: import.meta.env.VITE_REVERB_APP_KEY,
  wsHost: import.meta.env.VITE_REVERB_HOST,
  wsPort: Number(import.meta.env.VITE_REVERB_PORT ?? 80),
  wssPort: Number(import.meta.env.VITE_REVERB_PORT ?? 443),
  forceTLS: (import.meta.env.VITE_REVERB_SCHEME ?? "https") === "https",
  enabledTransports: ["ws", "wss"],
});

void createInertiaApp({
  // Keep the application's existing page resolution and other options here.
  withApp(app, { ssr }) {
    if (!ssr) {
      app.use(
        createMosaicast({
          echo: echo<"reverb">(),
          debug: import.meta.env.DEV,
        }),
      );
    }
  },
});

